class Solution {
    public boolean checkIfPangram(String sentence) {
        boolean[] seen = new boolean[26];
        int unique = 0;

        for (int i = 0; i < sentence.length(); i++) {
            int index = sentence.charAt(i) - 'a';
            if (!seen[index]) {
                seen[index] = true;
                unique++;
                if (unique == 26) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public boolean checkIfPangram(String sentence) {
        Set<Character> seen = new HashSet<>();
        for (int i = 0; i < sentence.length(); i++) {
            seen.add(sentence.charAt(i));
            if (seen.size() == 26) {
                return true;
            }
        }
        return false;
    }
}

class Solution {
    public boolean checkIfPangram(String sentence) {
        int mask = 0;
        int fullMask = (1 << 26) - 1;

        for (int i = 0; i < sentence.length(); i++) {
            mask |= 1 << (sentence.charAt(i) - 'a');
            if (mask == fullMask) {
                return true;
            }
        }
        return false;
    }
}

class Solution {
    public boolean checkIfPangram(String sentence) {
        for (char letter = 'a'; letter <= 'z'; letter++) {
            if (sentence.indexOf(letter) == -1) {
                return false;
            }
        }
        return true;
    }
}
